import{_ as i,o as t,c as o,a3 as a}from"./chunks/framework.vDgOMd_y.js";const c=JSON.parse('{"title":"Migrating from kimi-cli","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/migration.md","filePath":"en/guides/migration.md"}'),n={name:"en/guides/migration.md"};function r(s,e,d,l,g,m){return t(),o("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/migration.md for this page in Markdown format</div><h1 id="migrating-from-kimi-cli" tabindex="-1">Migrating from kimi-cli <a class="header-anchor" href="#migrating-from-kimi-cli" aria-label="Permalink to &quot;Migrating from kimi-cli&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Kimi Code CLI has gone through a major version upgrade — moving from Python/uv to Node.js, bringing a simpler install experience, faster startup, and a redesigned terminal UI. The legacy version will gradually be phased out, so we recommend upgrading as soon as possible.</p></div><p>If you are migrating from the legacy version, follow the steps below — a single command migrates your config, MCP servers, and session history to the new version.</p><h2 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h2><ul><li><strong>No more Python / uv</strong>: Rebuilt on Node.js — no Python environment needed, simpler to install</li><li><strong>Native binary, works out of the box</strong>: Faster startup, lighter footprint</li><li><strong>Redesigned terminal UI</strong>: Smoother, more responsive experience</li><li><strong>Full data migration</strong>: Config, MCP servers, and session history all carry over seamlessly</li></ul><h2 id="how-to-migrate" tabindex="-1">How to migrate <a class="header-anchor" href="#how-to-migrate" aria-label="Permalink to &quot;How to migrate&quot;">​</a></h2><p>There are two ways to migrate.</p><p>The <strong>first time you run <code>kimi</code></strong> after installing kimi-code, it automatically checks whether kimi-cli data exists under <code>~/.kimi/</code>. If it finds any, a migration prompt appears, and you can choose to migrate now, do it later, or never be asked again.</p><p>You can also <strong>run it manually at any time</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>You can choose whether to migrate chat sessions as well. If you don&#39;t need the history yet, pick <strong>Config only</strong>; otherwise pick <strong>Config + N sessions</strong> to bring everything across in one go. A summary is printed at the end.</p><h2 id="what-happens-during-migration" tabindex="-1">What happens during migration <a class="header-anchor" href="#what-happens-during-migration" aria-label="Permalink to &quot;What happens during migration&quot;">​</a></h2><p><strong>What gets migrated</strong>: configuration (<code>config.toml</code>), MCP server configuration, input history, and whichever chat sessions you chose to migrate.</p><p><strong>What does not get migrated</strong>: OAuth login credentials and MCP service authorizations are not copied, so you will need to run <code>/login</code> again and re-authorize MCP servers after migrating. kimi-cli plugins are also out of scope.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Migration <strong>never modifies or deletes</strong> any of the old data under <code>~/.kimi/</code>. kimi-cli keeps working as before, and the two do not interfere with each other. Migration can also be run repeatedly — sessions that have already been migrated are not imported again.</p></div><p>After migration, sessions imported from kimi-cli are tagged with <code>[imported]</code> in the session picker so you can tell them apart from new ones.</p>',17)])])}const p=i(n,[["render",r]]);export{c as __pageData,p as default};
